/**
 * Notes is part of the Portal now, but its address is where Outline's MCP
 * server was, and clients still point there. The appliance's proxy serves it
 * the way it serves the Portal's own: MCP and its sign-in go to the Portal,
 * anything else to the Notes page there.
 */
export const notesAppId = "kimono-notes";

export function notesSite(hostname: string, portalHostname: string) {
  return [
    "# Generated by Kimono. Do not edit; change the app in the Admin portal.",
    `${hostname} {`,
    "\tencode zstd gzip",
    "\t@mcp path /mcp /mcp/* /.well-known/oauth-protected-resource /.well-known/oauth-protected-resource/* /.well-known/oauth-authorization-server /.well-known/oauth-authorization-server/*",
    "\thandle @mcp {",
    "\t\treverse_proxy portal:3000",
    "\t}",
    "\thandle {",
    `\t\tredir https://${portalHostname}/notes 302`,
    "\t}",
    "}",
    "",
  ].join("\n");
}
